INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (581, 60005, "", "", 0, 2, 0, 0, 1, 2, 0, "今日の運勢は大吉！　日々の努力が実り、何事も良い方向へ！　　そんな弟くんには、お姉ちゃんのよしよしぎゅ～っをプレゼント♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (582, 60005, "", "", 0, 2, 0, 0, 2, 2, 0, "今日の運勢は大吉！　お出かけするといいことあるかも？　　　　また一緒に、お忍びデートしてくださいね……騎士♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (583, 60005, "", "", 0, 2, 0, 0, 2, 2, 0, "今日の運勢は大吉！　転居するならあたたかい場所が吉！　　　　煉獄の世なれど、住めば都と申しんす。ゆるりときなんせ……♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (584, 60005, "", "", 0, 3, 0, 0, 1, 2, 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！");
