INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (594, 60005, "", "", 0, 4, 0, 0, 1, 2, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (595, 60005, "", "", 0, 4, 0, 0, 1, 2, 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (596, 60005, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉！　空を眺めると気持ちが晴れやかに！　　　　眺めるだけじゃなくて、ひとっ飛びしちゃいましょうかっ♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (597, 60005, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉！　掃除をすると運勢が開けそう！　　　　　　「わ、めんど」「ヴルムっ！　新年早々サボっちゃダメなんだからね！」");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (598, 60005, "カリン", "", 2, 0, 0, 190804, 0, 3, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (599, 60005, "カリン", "", 3, 0, 7, 190804, 0, 3, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (600, 60006, "カリン", "", 1, 0, 0, 190804, 1, 1, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (601, 60006, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　勇気を持って、新しいことに挑戦しよう！\n幸先がいいねえ少年！　今年もいい一年になるよう祈ってるよ。");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (602, 60006, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　どんなピンチも簡単に乗り越えられそう！\nよい結果が出たようで何よりです。さて、待人の方は……ふふ。");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (603, 60006, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　あの人と仲直り……できちゃうかも！？\nはあ……この私があなたの運勢に興味を抱くわけないでしょう？");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (604, 60006, "", "", 0, 2, 0, 0, 1, 2, 0, "今日の運勢は大吉！　身近な友達との絆が深まる予感……？\n騎士様は、どなたと友誼を結ぶのでしょう？　気になります……");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (605, 60006, "", "", 0, 2, 0, 0, 2, 2, 0, "今日の運勢は大吉！　ラッキーアイテムは「蛇の抜け殻」！\nこのアタシにお目にかかれるなんて……アンタ、幸せものね♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (606, 60006, "", "", 0, 3, 0, 0, 2, 2, 0, "今日の運勢は中吉！　気になるあの人に会えちゃうかも！？\n『初夢を正夢にする枕』であなたに会え……な、なんでもない！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (607, 60006, "", "", 0, 3, 0, 0, 2, 2, 0, "今日の運勢は中吉！　子供に戻って、一日中遊びつくそう！\nお年玉でけん玉ゲット！　おじちゃん、もしかめ一万回やって！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (608, 60006, "", "", 0, 3, 0, 0, 1, 2, 0, "今日の運勢は中吉！　今日はおうちで、ゆーっくりくつろごう。\nお雑煮よし。みかんよし。さ、こたつで寝正月だ。君も入る？");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (609, 60006, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉！　突然のドッキリに注意！\nおや、後ろに髪の長い女の霊が──フフ、冗談です。私ですよ。");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (610, 60006, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉。慌てなくても、幸運はきっとやってくる。\n運は自分で掴むもの──媛が言ってました。でも、どうやって？");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (611, 60006, "カリン", "", 2, 0, 0, 190804, 0, 3, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (612, 60006, "カリン", "", 3, 0, 5, 190804, 0, 3, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (613, 60007, "カリン", "", 1, 0, 0, 190804, 1, 1, 0, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (614, 60007, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　絶好調で最高の一日になりそう♪\nわたしも、騎士クンが一緒ならいつだって最高に幸せな日だよ……");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (615, 60007, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　新しいことに挑戦するチャンス！\nお姉さんも一緒に挑戦しちゃおっかな♪　飲み処の新規開拓とか！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (616, 60007, "", "", 0, 1, 0, 0, 2, 2, 0, "今日の運勢は姫吉！　日々の努力が実を結ぶ予感！\n今日一日鍛錬に勤しむべき、ということだな。では早速行こうか。");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (617, 60007, "", "", 0, 2, 0, 0, 2, 2, 0, "今日の運勢は大吉！　家族サービスにはぴったりの日！\nさっそく弟くんにあまあまお姉ちゃんの出血大サービス、だよっ♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (618, 60007, "", "", 0, 2, 0, 0, 2, 2, 0, "今日の運勢は大吉！　笑顔で過ごせば周りもみんなハッピーかも！\n『笑う顔はフグになる』ですねっ。幸せいっぱいお届けしますっ");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (619, 60007, "", "", 0, 3, 0, 0, 2, 2, 0, "今日の運勢は中吉！　恋愛運良し、積極的な行動に成果が！？\nじゃあ騎士さんのこと、拉致しちゃうとか★　恋愛成就確定です♥");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (620, 60007, "", "", 0, 3, 0, 0, 2, 2, 0, "今日の運勢は中吉！　おめかししたら運気も上昇？\n毛並がふわふわになるまでブラッシングしたわ♪　ふふ、完璧ね！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (621, 60007, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉！　知らない場所に行くと新たな発見が！\n未知の場所……一人では恐ろしくて。騎士さま、どうかお力添えを");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (622, 60007, "", "", 0, 4, 0, 0, 2, 2, 0, "今日の運勢は小吉！　ラッキーアイテムは鳥の羽根！\nだからって、私の羽を毟ろうとしないでくださ～いっ！");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (623, 60007, "カリン", "", 2, 0, 0, 190804, 0, 3, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪");
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (624, 60007, "カリン", "", 3, 0, 5, 190804, 0, 3, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします");
